'use client';

import React, { useState } from 'react';
import { Search, Plus, Edit2, Trash2, Heart, Image as ImageIcon } from 'lucide-react';

interface Character {
  id: string;
  name: string;
  role: 'Protagonista' | 'Aliado' | 'Antagonista' | 'Secundário';
  age: number;
  mbti: string;
  motivation: string;
  relationship: string;
  hearts: number;
  imageUrl?: string;
}

export function CharactersSection() {
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState<string>('Todos');

  const [characters, setCharacters] = useState<Character[]>([
    {
      id: '1',
      name: 'Anya Silva',
      role: 'Protagonista',
      age: 23,
      mbti: 'INFJ',
      motivation: 'Salvar sua terra natal e descobrir a verdade sobre a magia arcaica.',
      relationship: 'Ben (Amigo)',
      hearts: 4,
      imageUrl: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&auto=format&fit=crop&q=80',
    },
    {
      id: '2',
      name: 'Ben Thorne',
      role: 'Aliado',
      age: 25,
      mbti: 'ESTP',
      motivation: 'Proteger Anya e pagar uma dívida do passado.',
      relationship: 'Anya (Guardião)',
      hearts: 5,
      imageUrl: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&auto=format&fit=crop&q=80',
    },
  ]);

  const categories = ['Todos', 'Protagonista', 'Aliado', 'Antagonista', 'Secundário'];

  const filteredCharacters = characters.filter((c) => {
    const matchesSearch = c.name.toLowerCase().includes(search.toLowerCase());
    const matchesFilter = filter === 'Todos' || c.role === filter;
    return matchesSearch && matchesFilter;
  });

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Pesquisa */}
      <div className="bg-[#f7eee3] p-4 rounded-2xl border border-[#d8c2aa] flex flex-col md:flex-row gap-4 items-center justify-between shadow-sm">
        <div className="relative w-full md:w-80">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-400" size={18} />
          <input
            type="text"
            placeholder="Pesquisar personagem..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-10 pr-4 py-2 bg-[#ebd9c6]/40 border border-[#d8c2aa] rounded-xl text-xs text-stone-800 placeholder-stone-400 focus:outline-none focus:ring-1 focus:ring-[#385338]"
          />
        </div>

        <div className="flex flex-wrap items-center gap-2 w-full md:w-auto">
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => setFilter(cat)}
              className={`px-3 py-1.5 rounded-lg text-xs font-semibold transition-colors ${
                filter === cat
                  ? 'bg-[#385338] text-white shadow-sm'
                  : 'bg-[#ebd9c6]/50 text-stone-700 hover:bg-[#d8c2aa]'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>

        <button className="w-full md:w-auto bg-[#385338] hover:bg-[#2c422c] text-white px-4 py-2 rounded-xl text-xs font-bold flex items-center justify-center gap-2 shadow-sm transition-colors">
          <Plus size={16} />
          <span>Novo Personagem</span>
        </button>
      </div>

      {/* Lista de Personagens */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {filteredCharacters.map((char) => (
          <div
            key={char.id}
            className="bg-[#f7eee3] border border-[#d8c2aa] rounded-2xl p-5 shadow-sm space-y-4 relative"
          >
            {/* Cabeçalho do Cartão com Avatar */}
            <div className="flex items-start justify-between">
              <div className="flex items-center gap-3">
                {char.imageUrl ? (
                  <img
                    src={char.imageUrl}
                    alt={char.name}
                    className="w-14 h-14 rounded-xl object-cover border-2 border-[#d8c2aa] shadow-inner"
                  />
                ) : (
                  <div className="w-14 h-14 bg-amber-200 border border-amber-300 rounded-xl flex items-center justify-center font-bold text-[#7a5230] text-xl shadow-inner">
                    {char.name.charAt(0)}
                  </div>
                )}
                <div>
                  <h3 className="font-serif font-bold text-lg text-stone-900">{char.name}</h3>
                  <span className="text-[11px] font-medium bg-[#ebd9c6] text-[#7a5230] px-2.5 py-0.5 rounded-full border border-[#d8c2aa]/60 inline-block mt-0.5">
                    {char.role}
                  </span>
                </div>
              </div>

              <div className="flex items-center gap-2 text-stone-400">
                <button className="hover:text-stone-700 transition-colors">
                  <Edit2 size={16} />
                </button>
                <button className="hover:text-red-600 transition-colors">
                  <Trash2 size={16} />
                </button>
              </div>
            </div>

            {/* Informações Idade / MBTI */}
            <div className="grid grid-cols-2 bg-[#ebd9c6]/40 border border-[#d8c2aa]/60 rounded-xl p-2.5 text-xs text-stone-700 font-medium text-center">
              <div>
                <span>Idade: </span>
                <strong className="text-stone-900">{char.age} anos</strong>
              </div>
              <div className="border-l border-[#d8c2aa]/60">
                <span>MBTI: </span>
                <strong className="text-stone-900">{char.mbti}</strong>
              </div>
            </div>

            {/* Motivação */}
            <div className="space-y-1">
              <span className="text-[11px] font-bold text-stone-800">Motivação:</span>
              <p className="text-xs text-stone-600 italic leading-relaxed">
                "{char.motivation}"
              </p>
            </div>

            {/* Relação e Nível de Afeto */}
            <div className="pt-3 border-t border-[#d8c2aa]/60 flex items-center justify-between text-xs">
              <span className="text-stone-700">
                Relação: <strong className="text-stone-900">{char.relationship}</strong>
              </span>
              <div className="flex items-center gap-1 text-red-500">
                {[1, 2, 3, 4, 5].map((star) => (
                  <Heart
                    key={star}
                    size={14}
                    fill={star <= char.hearts ? '#ef4444' : 'none'}
                    className={star <= char.hearts ? 'text-red-500' : 'text-stone-300'}
                  />
                ))}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}